const moveToGrace = `-- name: MoveToGrace :one
UPDATE billing_subscriptions
SET status = 'grace',
    grace_ends_at = $1,
    note = CASE
        WHEN note = '' THEN 'lifecycle: moved to grace'
        ELSE note || E'\n' || 'lifecycle: moved to grace'
    END
WHERE id = $2 AND status IN ('trial', 'active')
RETURNING id, uuid, organization_id, plan_id, period, status, starts_at, ends_at, grace_ends_at, price_paid, credit_balance, custom_features, source, note, created_by, created_at, updated_at
`

